    const days=new Map(),weekday=Array(7).fill(0);rows.forEach(o=>{const d=dayK(o.created_at);if(!days.has(d))days.set(d,{n:0,done:0});const x=days.get(d);x.n++;if(o.status==='delivered')x.done++;weekday[new Date(o.created_at).getDay()]++;});
